#![forbid(unsafe_code)]
#![warn(clippy::let_underscore_future)]
//! hkask-mcp-nostr-blossom — local Blossom media sidecar.

pub mod auth;
pub mod config;
pub mod http;
pub mod ontology;
pub mod server;
pub mod storage;

use std::sync::Arc;

use config::{Config, default_store_dir};
use server::{
    AnnouncementGuard, BlossomState, ListenerState, NostrBlossomServer, announce_listener,
    default_announcement_path,
};
use storage::BlobStore;

// Generated by `build.rs` from the `#[tool]` fn signatures in `src/*.rs`.
include!(concat!(env!("OUT_DIR"), "/tool_names.gen.rs"));

pub struct RunningServer {
    pub state: Arc<BlossomState>,
    pub announcement: AnnouncementGuard,
    pub task: Option<tokio::task::JoinHandle<()>>,
}

pub async fn start_with(
    config: Config,
    store_dir: std::path::PathBuf,
    announcement_path: std::path::PathBuf,
) -> Result<RunningServer, hkask_mcp_server::McpError> {
    let infrastructure = |err: storage::StorageError| {
        hkask_mcp_server::McpError::Infrastructure(hkask_types::InfrastructureError::Io(
            err.to_string(),
        ))
    };
    let store = Arc::new(BlobStore::open(store_dir.clone()).map_err(infrastructure)?);

    let (bound, listener_state) = match http::bind(config.port).await {
        Ok((listener, addr)) => (Some((listener, addr)), ListenerState::Listening(addr)),
        Err(error) => {
            tracing::warn!(port = config.port, %error, "blossom HTTP listener did not bind");
            (None, ListenerState::Down(error.to_string()))
        }
    };

    let state = Arc::new(BlossomState::new(store, config, store_dir, listener_state));
    let announcement = announce_listener(&state.listener, &announcement_path)
        .unwrap_or_else(|_| AnnouncementGuard::empty());

    let task = bound.map(|(listener, addr)| {
        let state_clone = Arc::clone(&state);
        tokio::spawn(async move {
            http::serve(listener, state_clone, addr.port()).await;
        })
    });

    Ok(RunningServer {
        state,
        announcement,
        task,
    })
}

pub async fn run() -> Result<(), hkask_mcp_server::McpError> {
    let running = start_with(
        Config::from_env(),
        default_store_dir(),
        default_announcement_path(),
    )
    .await?;

    let state = Arc::clone(&running.state);
    let result = hkask_mcp_server::run_server(
        "hkask-mcp-nostr-blossom",
        env!("CARGO_PKG_VERSION"),
        move |ctx: hkask_mcp_server::ServerContext| {
            Ok(NostrBlossomServer::new(ctx.webid, Arc::clone(&state)))
        },
        Vec::new(),
    )
    .await;
    drop(running.announcement);
    if let Some(task) = running.task {
        task.abort();
    }
    result
}

#[cfg(test)]
mod tool_surface_tests {
    use super::*;

    hkask_mcp_server::tool_surface_pin!(
        crate::server::NostrBlossomServer::nostr_blossom_router(),
        "nostr_blossom_router",
        3,
        tool_surface_is_exactly_3_registered_tools,
    );

    #[test]
    fn wire_tool_names_match_the_generated_list() {
        let mut generated: Vec<&str> = TOOL_NAMES.to_vec();
        generated.sort_unstable();
        assert_eq!(generated, hkask_types::nostr_wire::BLOSSOM_TOOL_NAMES);
    }

    #[test]
    fn live_router_schemas_are_strict_for_all_registered_tools() {
        let tools = crate::server::NostrBlossomServer::nostr_blossom_router().list_all();
        assert_eq!(tools.len(), 3);
        for tool in tools {
            let schema =
                serde_json::to_value(&tool.input_schema).expect("router schema serializes");
            let violations = hkask_types::find_boolean_schema_positions(&schema);
            assert!(
                violations.is_empty(),
                "{} live schema contains bare-boolean positions: {violations:?}",
                tool.name
            );
        }
    }

    #[test]
    fn no_tool_writes_policy_or_deletes_events() {
        for name in TOOL_NAMES {
            for verb in [
                "delete", "remove", "allow", "config", "set_", "wipe", "publish", "sign",
            ] {
                assert!(
                    !name.contains(verb),
                    "tool {name} looks like a policy or delete verb ({verb})"
                );
            }
        }
    }
}

#[cfg(test)]
mod integration_tests {
    use super::*;
    use hkask_nostr_core::{Event, event_id};
    use k256::schnorr::SigningKey;
    use k256::schnorr::signature::hazmat::PrehashSigner;
    use sha2::{Digest, Sha256};
    use std::collections::BTreeSet;

    fn pubkey_of(secret: [u8; 32]) -> [u8; 32] {
        SigningKey::from_bytes(&secret.into())
            .expect("valid signing key")
            .verifying_key()
            .to_bytes()
            .into()
    }

    fn sign_auth_event(
        secret: [u8; 32],
        action: &str,
        sha256: &str,
        domain: Option<&str>,
    ) -> String {
        let signing_key = SigningKey::from_bytes(&secret.into()).expect("valid signing key");
        let pubkey: [u8; 32] = signing_key.verifying_key().to_bytes().into();
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        let created_at = now.saturating_sub(5);
        let mut tags = vec![
            vec!["t".to_string(), action.to_string()],
            vec!["expiration".to_string(), (now + 600).to_string()],
            vec!["x".to_string(), sha256.to_string()],
        ];
        if let Some(d) = domain {
            tags.push(vec!["server".to_string(), d.to_string()]);
        }
        let id = event_id(&pubkey, created_at, 24_242, &tags, "Blossom auth");
        let sig = signing_key.sign_prehash(&id).expect("signs");
        let event = Event::from_parts(
            pubkey,
            created_at,
            24_242,
            tags,
            "Blossom auth".to_string(),
            sig.to_bytes(),
        )
        .expect("verified");
        let encoded = base64::engine::Engine::encode(
            &base64::engine::general_purpose::STANDARD,
            event.to_json(),
        );
        format!("Nostr {encoded}")
    }

    fn sign_delete_auth(secret: [u8; 32], sha256: &str) -> String {
        sign_auth_event(secret, "delete", sha256, None)
    }

    fn sign_upload_auth(secret: [u8; 32], sha256: &str, domain: &str) -> String {
        sign_auth_event(secret, "upload", sha256, Some(domain))
    }

    #[tokio::test]
    async fn streaming_upload_head_range_get_and_refcounted_delete() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let store_dir = tmp.path().join("blossom");
        let ann_path = store_dir.join("listener.json");

        let author_a = [11u8; 32];
        let author_b = [22u8; 32];
        let stranger = [33u8; 32];
        let pk_a = pubkey_of(author_a);
        let pk_b = pubkey_of(author_b);

        let cfg = Config {
            port: 0,
            max_bytes: 1024 * 1024,
            public_base_url: None,
            public_host: None,
            allowed_authors: BTreeSet::from([pk_a, pk_b]),
            refused: Vec::new(),
        };
        let running = start_with(cfg, store_dir.clone(), ann_path.clone())
            .await
            .expect("starts");
        let addr = match running.state.listener {
            ListenerState::Listening(a) => a,
            ListenerState::Down(ref r) => panic!("listener down: {r}"),
        };
        let base = format!("http://{addr}");
        let domain = addr.to_string();

        let ann_text = std::fs::read_to_string(&ann_path).expect("announcement written");
        assert!(ann_text.contains(&base));

        let payload = b"0123456789abcdefghijklmnopqrstuvwxyzMP4DATA";
        let sha = hex::encode(Sha256::digest(payload));
        let client = reqwest::Client::new();

        // 1. Non-allowlisted author is refused on HEAD /upload.
        let stranger_auth = sign_upload_auth(stranger, &sha, &domain);
        let head_stranger = client
            .head(format!("{base}/upload"))
            .header("Authorization", &stranger_auth)
            .header("X-SHA-256", &sha)
            .header("X-Content-Length", payload.len().to_string())
            .send()
            .await
            .unwrap();
        assert_eq!(head_stranger.status(), reqwest::StatusCode::FORBIDDEN);

        // 2. BUD-06 HEAD /upload succeeds for allowlisted author A.
        let auth_a = sign_upload_auth(author_a, &sha, &domain);
        let head_ok = client
            .head(format!("{base}/upload"))
            .header("Authorization", &auth_a)
            .header("X-SHA-256", &sha)
            .header("X-Content-Length", payload.len().to_string())
            .header("X-Content-Type", "video/mp4")
            .send()
            .await
            .unwrap();
        assert_eq!(head_ok.status(), reqwest::StatusCode::OK);

        // 3. Mismatched SHA-256 on PUT /upload is rejected and leaves no blob.
        let bad_put = client
            .put(format!("{base}/upload"))
            .header("Authorization", &auth_a)
            .header("Content-Type", "video/mp4")
            .header("X-SHA-256", &sha)
            .body(b"corrupted-bytes".to_vec())
            .send()
            .await
            .unwrap();
        assert_eq!(bad_put.status(), reqwest::StatusCode::BAD_REQUEST);
        assert!(running.state.store.get_blob(&sha).unwrap().is_none());

        // 4. Valid PUT /upload by author A succeeds and returns BlobDescriptor.
        let put_a = client
            .put(format!("{base}/upload"))
            .header("Authorization", &auth_a)
            .header("Content-Type", "video/mp4")
            .header("X-SHA-256", &sha)
            .body(payload.to_vec())
            .send()
            .await
            .unwrap();
        assert_eq!(put_a.status(), reqwest::StatusCode::OK);
        let desc: serde_json::Value = put_a.json().await.unwrap();
        assert_eq!(desc["sha256"], sha);
        assert_eq!(desc["url"], format!("{base}/{sha}.mp4"));
        assert_eq!(desc["size"], payload.len() as u64);
        assert_eq!(desc["type"], "video/mp4");

        // 5. Byte-range GET /<sha256>.mp4 returns 206 Partial Content + CORS.
        let range_get = client
            .get(format!("{base}/{sha}.mp4"))
            .header("Range", "bytes=10-19")
            .send()
            .await
            .unwrap();
        assert_eq!(range_get.status(), reqwest::StatusCode::PARTIAL_CONTENT);
        assert_eq!(
            range_get
                .headers()
                .get("access-control-allow-origin")
                .and_then(|v| v.to_str().ok()),
            Some("*")
        );
        assert_eq!(
            range_get
                .headers()
                .get("content-range")
                .and_then(|v| v.to_str().ok()),
            Some(format!("bytes 10-19/{}", payload.len()).as_str())
        );
        assert_eq!(range_get.bytes().await.unwrap().as_ref(), b"abcdefghij");

        // 6. Author B also uploads the same blob -> 2 owners; A deletes -> blob stays; B deletes -> blob unlinked.
        let auth_b = sign_upload_auth(author_b, &sha, &domain);
        let put_b = client
            .put(format!("{base}/upload"))
            .header("Authorization", &auth_b)
            .header("Content-Type", "video/mp4")
            .header("X-SHA-256", &sha)
            .body(payload.to_vec())
            .send()
            .await
            .unwrap();
        assert_eq!(put_b.status(), reqwest::StatusCode::OK);

        let list_a: Vec<serde_json::Value> = client
            .get(format!("{base}/list/{}", hex::encode(pk_a)))
            .send()
            .await
            .unwrap()
            .json()
            .await
            .unwrap();
        assert_eq!(list_a.len(), 1);
        assert_eq!(list_a[0]["sha256"], sha);

        let del_a = client
            .delete(format!("{base}/{sha}"))
            .header("Authorization", sign_delete_auth(author_a, &sha))
            .send()
            .await
            .unwrap();
        assert_eq!(del_a.status(), reqwest::StatusCode::OK);
        let del_a_json: serde_json::Value = del_a.json().await.unwrap();
        assert_eq!(del_a_json["blob_unlinked"], false);
        assert_eq!(del_a_json["remaining_owners"], 1);
        assert!(running.state.store.blob_path(&sha).is_file());

        let del_b = client
            .delete(format!("{base}/{sha}"))
            .header("Authorization", sign_delete_auth(author_b, &sha))
            .send()
            .await
            .unwrap();
        assert_eq!(del_b.status(), reqwest::StatusCode::OK);
        let del_b_json: serde_json::Value = del_b.json().await.unwrap();
        assert_eq!(del_b_json["blob_unlinked"], true);
        assert!(!running.state.store.blob_path(&sha).exists());
        assert!(running.state.store.get_blob(&sha).unwrap().is_none());

        drop(running.announcement);
        assert!(!ann_path.exists());
        if let Some(t) = running.task {
            t.abort();
        }
    }

    #[tokio::test]
    async fn announcement_guard_preserves_live_other_instance() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let store_a = tmp.path().join("a");
        let store_b = tmp.path().join("b");
        let ann_path = tmp.path().join("listener.json");

        let running_a = start_with(Config::default(), store_a, ann_path.clone())
            .await
            .expect("a starts");
        let ann_a = std::fs::read_to_string(&ann_path).expect("a announced");

        let running_b = start_with(Config::default(), store_b, ann_path.clone())
            .await
            .expect("b starts");
        assert_eq!(std::fs::read_to_string(&ann_path).unwrap(), ann_a);
        drop(running_b.announcement);
        assert_eq!(std::fs::read_to_string(&ann_path).unwrap(), ann_a);

        drop(running_a.announcement);
        assert!(!ann_path.exists());
        if let Some(t) = running_a.task {
            t.abort();
        }
        if let Some(t) = running_b.task {
            t.abort();
        }
    }
}
